import random,statistics
seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">"))
comp=str.maketrans("ACGT","TGCA")
stops=('TAA','TAG','TGA')
def longest_orf(s):
    best=0
    for f in range(3):
        i=f
        while i+3<=len(s):
            if s[i:i+3]=='ATG':
                j=i+3
                while j+3<=len(s) and s[j:j+3] not in stops:
                    j+=3
                if j-i>best: best=j-i
                i=j
            else:
                i+=3
    return best
def both(s):
    return max(longest_orf(s),longest_orf(s.translate(comp)[::-1]))
real=both(seq)
print("real longest ATG-stop ORF bp:",real,"aa",real//3)
random.seed(2)
vals=[both("".join(random.sample(seq,len(seq)))) for _ in range(500)]
print("shuffled mean",statistics.mean(vals),"max",max(vals))
print("frac >= real", sum(v>=real for v in vals)/len(vals))
